-- Flyway V2: 初始种子数据（弹幕模板、游戏内容、结局模板、风险债务等）
-- 从原 data.sql 迁移而来，由 Flyway 接管执行。
-- H2 在 MODE=MySQL 下可正常执行（ON DUPLICATE KEY UPDATE 已验证兼容）。

INSERT INTO p0_seed_manifest (seed_key, seed_category, display_name, expected_count, detail)
VALUES
    ('actions', 'core_loop', '9个P0主行动', 9, '练歌、练舞、杂谈复盘、直播企划、发布视频、发布切片、粉丝群维护、同台互动、休息'),
    ('stream_plans', 'stream', '12个直播企划', 12, '唱歌、舞蹈、杂谈、游戏、突击、棉花糖、锐评、耐久、联动、歌杂混合、短视频挑战、高亮互动答谢'),
    ('title_styles', 'stream', '直播标题三风格', 3, 'SAFE、BAIT_TRAFFIC、HARD_MOUTH/ABSTRACT_MEME'),
    ('risk_debts', 'risk', '4类P0后续债务', 4, '标题党反噬、回旋镖切片、独角兽期待、商业反噬'),
    ('risk_tools', 'risk', '3个米线工具', 3, '降温公告、切片反转、临时房管'),
    ('ending_templates', 'ending', '9个主结局图片与模板', 9, 'UNKNOWN、ELECTRONIC_PICKLE、SINGING_IDOL、SLICE_SAINT、BLACK_RED_MAIN_STAGE、CYBER_GIRLFRIEND、DD_BUS_STOP、MAIN_STAGE_KING、GLORIOUS_GRADUATION')
ON DUPLICATE KEY UPDATE
    seed_category = VALUES(seed_category),
    display_name = VALUES(display_name),
    expected_count = VALUES(expected_count),
    detail = VALUES(detail);

