-- ============================================================
-- 扩充内容F: NARRATIVE_TEXT 叙事文本 (60条)
-- ============================================================

DELETE FROM game_content WHERE category = 'NARRATIVE_TEXT';
INSERT INTO game_content (category, content_key, sub_key, content_text, content_json, sort_order, enabled) VALUES
('NARRATIVE_TEXT', 'VIRAL_CLIP', 'safe', '切片走红的safe选择叙事', '{"safeText":"你选择低调处理，发了一条感谢动态。切片组表示理解，弹幕说主播很稳。热度慢慢散去，但你的口碑分数悄悄上升了。","trafficText":"你没有借势营销，但老粉们在群里说主播很有分寸。切片组说素材可以慢慢发，不急。评论区的风向从热闹变成了认可。","memeText":"你选择低调感谢，没有追加内容。弹幕说主播很稳重，老粉表示欣慰。虽然没有接住最大流量，但口碑稳住了。"}', 1, TRUE),
('NARRATIVE_TEXT', 'VIRAL_CLIP', 'traffic', '切片走红的traffic选择叙事', '{"safeText":"你决定硬接流量，立刻开了一场加播。弹幕涌入大量新观众，人气飙升。但老粉发现弹幕质量在下降，开始在群里抱怨。","trafficText":"你趁热打铁发了三个相关视频，流量确实接住了。但标题组说标题已经用到了极限，再推就要反噬。评论区开始出现质疑的声音。","memeText":"你全力接住流量，准备了特别内容。新观众涌入的同时，弹幕开始变得不可控。房管说今天的控场难度是平时的三倍。"}', 2, TRUE),
('NARRATIVE_TEXT', 'VIRAL_CLIP', 'meme', '切片走红的meme选择叙事', '{"safeText":"你顺势玩梗，发了一条抽象动态回应。弹幕笑疯了，切片组说这条动态本身又能剪一条切片。串味值上升，但口碑没掉。","trafficText":"你用梗的方式回应，评论区变成了大型玩梗现场。标题组说这个回应本身比原切片还有传播力。流量自然发酵，没有反噬。","memeText":"你选择官方玩梗，自己转发了切片并加了神评论。弹幕说主播太会了，乐子人表示满意。这个操作本身又产生了新的素材。"}', 3, TRUE),
('NARRATIVE_TEXT', 'TITLE_BACKFIRE', 'safe', '标题党反噬的safe选择叙事', '{"safeText":"你承认标题过于夸张，发了一条道歉动态。弹幕说主播认错态度好，口碑开始回升。但标题组表示以后要收敛一点了。","trafficText":"你低调处理，没有公开回应。弹幕的骂声慢慢消退，但口碑已经受损。考据组说这段以后会被反复提起。","memeText":"你选择安静道歉，不搞花活。弹幕说主播态度端正，老粉表示理解。虽然热度降了，但口碑开始修复。"}', 4, TRUE),
('NARRATIVE_TEXT', 'TITLE_BACKFIRE', 'traffic', '标题党反噬的traffic选择叙事', '{"safeText":"你硬扛下去，继续用夸张标题。流量确实没掉，但口碑持续下降。楼友说主播在走钢丝，迟早要摔。","trafficText":"你选择无视质疑，继续按自己的方式来。弹幕分裂成两派，一派支持一派反对。人气没掉，但串味值在飙升。","memeText":"你决定和标题组对着干，自己改了标题。标题组表示不满，但弹幕说主播终于清醒了。口碑开始回升，但流量也降了。"}', 5, TRUE),
('NARRATIVE_TEXT', 'TITLE_BACKFIRE', 'meme', '标题党反噬的meme选择叙事', '{"safeText":"你自嘲标题组太会写了，发了一条玩梗动态。弹幕笑疯了，争议变成了节目效果。口碑虽然没完全恢复，但至少止血了。","trafficText":"你用幽默化解争议，说标题组在加班。弹幕说主播的控场能力又提升了。标题党反噬变成了新的素材。","memeText":"你顺势玩梗，把标题党变成了长期梗。弹幕说以后每次标题夸张都可以说标题组又在加班了。争议变成了特色。"}', 6, TRUE),
('NARRATIVE_TEXT', 'COLLAB_CONTROVERSY', 'safe', '联动争议的safe选择叙事', '{"safeText":"你解释了联动的考量，态度诚恳。弹幕说主播有想法，部分独角兽表示理解。但还是有一部分粉丝选择了离开。","trafficText":"你发了一篇长文说明联动的原因。弹幕分成两派，但支持的声音更多。考据组说主播的解释很详细，没有漏洞。","memeText":"你选择低调回应，简单说明情况。弹幕说主播的态度可以，但独角兽群的气压还是很低。口碑在缓慢修复。"}', 7, TRUE),
('NARRATIVE_TEXT', 'COLLAB_CONTROVERSY', 'traffic', '联动争议的traffic选择叙事', '{"safeText":"你坚持联动路线，没有妥协。DD们表示支持，但独角兽们开始集体表达不满。人气在上升，但真爱粉在流失。","trafficText":"你高调宣布继续联动，弹幕瞬间炸了。支持和反对的声音各占一半。楼友说主播在赌，赌赢了就是新路线，赌输了就是口碑暴跌。","memeText":"你选择硬扛，坚持自己的社交策略。弹幕说主播有主见，但独角兽群已经有人在退群了。人气上去了，但基本盘在动摇。"}', 8, TRUE),
('NARRATIVE_TEXT', 'COLLAB_CONTROVERSY', 'meme', '联动争议的meme选择叙事', '{"safeText":"你用幽默化解争议，说联动是因为对面主播欠你一顿饭。弹幕笑疯了，紧张气氛瞬间缓解。独角兽虽然还有意见，但至少不那么激烈了。","trafficText":"你玩梗回应，说DD来去自由，联动是给大家多一个选择。弹幕说主播太会说话了。争议变成了节目效果。","memeText":"你顺势玩梗，说联动是为了让弹幕有更多瓜可以吃。乐子人表示满意，但独角兽说主播在回避问题。争议暂时搁置。"}', 9, TRUE),
('NARRATIVE_TEXT', 'FAN_DRAMA', 'safe', '粉丝内讧的safe选择叙事', '{"safeText":"你发了一条群公告呼吁冷静。弹幕说主播的态度很稳，两派人暂时消停了。但根本矛盾没有解决，只是暂时搁置。","trafficText":"你分别和两派负责人私聊，了解情况。弹幕说主播很用心，但群里的气氛还是很微妙。口碑没掉，但管理难度在上升。","memeText":"你选择发公告平息事态，不公开表态。弹幕说主播在装死，但老粉说这是最稳妥的做法。热度慢慢降下来了。"}', 10, TRUE),
('NARRATIVE_TEXT', 'FAN_DRAMA', 'traffic', '粉丝内讧的traffic选择叙事', '{"safeText":"你在直播中公开调解，弹幕瞬间炸了。支持你的人说主播有担当，反对的人说你在和稀泥。口碑波动很大。","trafficText":"你选择在群里公开讨论，让双方把话说开。弹幕说主播很勇敢，但也有人说你在制造更多争议。围观值在上升。","memeText":"你公开表态支持其中一方，弹幕瞬间分裂。支持的人更加支持，反对的人更加反对。口碑暴跌，但真爱粉反而更坚定了。"}', 11, TRUE),
('NARRATIVE_TEXT', 'FAN_DRAMA', 'meme', '粉丝内讧的meme选择叙事', '{"safeText":"你装死处理，完全不参与。弹幕说主播在装死，但热度确实降了。粉丝们自己吵累了，最后不了了之。","trafficText":"你用玩梗的方式回应，说弹幕在搞互联网大辩论。乐子人表示满意，但两派人都觉得你在回避问题。","memeText":"你选择幽默化解，说今天的弹幕比直播还精彩。弹幕笑了一部分，但核心矛盾还是没有解决。只是暂时缓解了紧张气氛。"}', 12, TRUE),
('NARRATIVE_TEXT', 'PLATFORM_THROTTLE', 'safe', '平台限流的safe选择叙事', '{"safeText":"你检查了自己的内容，发现可能触碰了某些规则。你调整了内容方向，弹幕说主播很细心。流量慢慢恢复了。","trafficText":"你低调调整策略，不公开讨论限流的事。弹幕没有察觉到变化，但你的数据在缓慢恢复。老粉说最近的直播质量没掉。","memeText":"你选择按新标准调整内容，不抱怨平台。弹幕说主播很专业，虽然流量降了但口碑没掉。数据在慢慢回升。"}', 13, TRUE),
