('NARRATIVE_TEXT', 'COPY_STRIKE', 'traffic', '被抄袭的traffic选择叙事', '{"safeText":"你公开维权，发动态指出抄袭。弹幕炸了，支持你的人很多，但也有人说你在蹭热度。抄袭者道歉了，但你的口碑也受到了一些影响。","trafficText":"你公开维权，弹幕瞬间分成两派。支持你的人说你有理，反对的人说你小题大做。事情闹大了，但抄袭者确实道歉了。","memeText":"你高调维权，弹幕说主播终于硬气了一回。抄袭者被舆论压力逼得道歉了。但你的形象也从温和变成了强硬。"}', 17, TRUE),
