('NARRATIVE_TEXT', 'MEME_OVERCOOKED', 'meme', '梗被玩坏了的meme选择叙事', '{"safeText":"你用幽默引导方向，弹幕笑疯了。梗的热度开始下降，但串味值还是很高。口碑略有下降。","trafficText":"你玩梗回应，说这个梗已经被玩坏了。弹幕笑了一部分，梗的热度开始消退。口碑稳住了。","memeText":"你用抽象方式化解，弹幕说主播太会了。梗的热度开始下降，口碑没有受到太大影响。"}', 36, TRUE),
('NARRATIVE_TEXT', 'COMMERC试探', 'safe', '商业化试探的safe选择叙事', '{"safeText":"你减少了商业化内容的频率，弹幕说主播很听劝。口碑开始回升，但运营预算下降了。","trafficText":"你选择低调调整，不公开讨论商业化的事。弹幕没有察觉到变化，口碑在缓慢恢复。","memeText":"你安静地减少商业化内容，弹幕说主播很稳。口碑在回升，但商业化进度慢了。"}', 37, TRUE),
('NARRATIVE_TEXT', 'COMMERC试探', 'traffic', '商业化试探的traffic选择叙事', '{"safeText":"你继续尝试商业化内容，弹幕开始抱怨。口碑持续下降，但运营预算在上升。楼友说主播在赌口碑。","trafficText":"你高调推进商业化，弹幕瞬间炸了。反对的声音很多，但你也收获了一批商业化的支持者。口碑暴跌。","memeText":"你坚持商业化路线，弹幕说主播变了。口碑在下降，但你在商业化方面积累了经验。"}', 38, TRUE),
('NARRATIVE_TEXT', 'COMMERC试探', 'meme', '商业化试探的meme选择叙事', '{"safeText":"你用梗的方式解释商业化，弹幕笑疯了。商业化内容变得不那么突兀了，口碑没有受到太大影响。","trafficText":"你玩梗回应商业化质疑，弹幕说主播太会了。商业化内容变成了节目效果，口碑稳住了。","memeText":"你用幽默化解商业化争议，弹幕笑了一部分。商业化进度没变，但口碑稳住了。"}', 39, TRUE),
('NARRATIVE_TEXT', 'EQUIPMENT_BREAK', 'safe', '设备损坏的safe选择叙事', '{"safeText":"你结束直播去修设备，弹幕说主播很负责。口碑没有受到太大影响，但今天的直播数据下降了。","trafficText":"你选择暂停直播修设备，弹幕表示理解。口碑没有受到太大影响，但今天的直播提前结束了。","memeText":"你安静地结束直播，弹幕说主播很稳。口碑没有受到太大影响，但今天的直播时长短了。"}', 40, TRUE),
('NARRATIVE_TEXT', 'EQUIPMENT_BREAK', 'traffic', '设备损坏的traffic选择叙事', '{"safeText":"你用备用设备继续直播，弹幕说主播很敬业。直播质量下降了，但人气没有掉太多。","trafficText":"你坚持直播，弹幕说主播很努力。但声音质量很差，观众开始流失。口碑略有下降。","memeText":"你硬撑着继续直播，弹幕说主播在坚持。但直播质量太差了，观众开始抱怨。口碑下降了。"}', 41, TRUE),
('NARRATIVE_TEXT', 'EQUIPMENT_BREAK', 'meme', '设备损坏的meme选择叙事', '{"safeText":"你把设备故障变成梗，弹幕笑疯了。直播质量下降了，但节目效果上升了。口碑没有受到太大影响。","trafficText":"你玩梗设备故障，弹幕说主播太会了。直播质量虽然差了，但弹幕很欢乐。口碑稳住了。","memeText":"你用幽默化解设备故障，弹幕笑了一部分。直播质量下降了，但气氛很好。口碑稳住了。"}', 42, TRUE),
('NARRATIVE_TEXT', 'FAN_CAMPAIGN', 'safe', '粉丝应援的safe选择叙事', '{"safeText":"你在直播中表达感谢，弹幕说主播很真诚。粉丝们表示满意，口碑上升了。","trafficText":"你选择低调感谢，不搞花活。弹幕说主播很稳，粉丝们表示理解。口碑稳住了。","memeText":"你安静地表达感谢，弹幕说主播很真诚。口碑上升了，粉丝们更加支持你了。"}', 43, TRUE),
('NARRATIVE_TEXT', 'FAN_CAMPAIGN', 'traffic', '粉丝应援的traffic选择叙事', '{"safeText":"你转发应援内容，弹幕瞬间炸了。支持你的粉丝更加兴奋了，但也有人说你在蹭自己的热度。口碑略有波动。","trafficText":"你高调感谢粉丝，弹幕说主播很会做人。口碑上升了，但有人说你太会营销了。","memeText":"你搞了个感谢直播，弹幕说主播很用心。口碑上升了，但直播数据没有预期的好。"}', 44, TRUE),
('NARRATIVE_TEXT', 'FAN_CAMPAIGN', 'meme', '粉丝应援的meme选择叙事', '{"safeText":"你用搞笑方式回应粉丝的心意，弹幕笑疯了。粉丝们表示很开心，口碑上升了。","trafficText":"你玩梗感谢粉丝，弹幕说主播太会了。粉丝们被你逗笑了，口碑上升了。","memeText":"你用幽默化解感动的气氛，弹幕笑了一部分。粉丝们表示主播很有趣，口碑稳住了。"}', 45, TRUE),
('NARRATIVE_TEXT', 'BIG_V_RETWEET', 'safe', '被大V转发的safe选择叙事', '{"safeText":"你私信感谢大V，弹幕说主播很懂社交。口碑上升了，大V的粉丝开始关注你。","trafficText":"你选择低调致谢，不公开回应。弹幕不知道发生了什么，但你的粉丝数在上升。","memeText":"你安静地表达感谢，弹幕说主播很稳。口碑上升了，大V的粉丝开始涌入。"}', 46, TRUE),
('NARRATIVE_TEXT', 'BIG_V_RETWEET', 'traffic', '被大V转发的traffic选择叙事', '{"safeText":"你在评论区和大V互动，弹幕瞬间炸了。大V的粉丝开始涌入你的直播间，人气飙升。但老粉说弹幕质量在下降。","trafficText":"你公开互动大V，弹幕说主播在蹭热度。大V的粉丝涌入的同时，弹幕开始变得不可控。口碑略有下降。","memeText":"你高调和大V互动，弹幕说主播太会社交了。大V的粉丝开始关注你，但弹幕质量在下降。"}', 47, TRUE),
('NARRATIVE_TEXT', 'BIG_V_RETWEET', 'meme', '被大V转发的meme选择叙事', '{"safeText":"你用梗的方式表示感谢，弹幕笑疯了。大V也被你逗笑了，互动很愉快。口碑上升了，弹幕质量没有下降。","trafficText":"你玩梗回关大V，弹幕说主播太会了。大V的粉丝开始关注你，弹幕质量没有下降。口碑上升了。","memeText":"你用幽默回应大V的转发，弹幕笑了一部分。大V表示你很有趣，口碑上升了。"}', 48, TRUE),
('NARRATIVE_TEXT', 'TRENDING_TOPIC', 'safe', '话题上热搜的safe选择叙事', '{"safeText":"你先不动，等热度自然发酵。弹幕说主播很稳，热度慢慢散去了。口碑没有受到太大影响。","trafficText":"你选择低调处理，不公开回应。弹幕的热度慢慢降下来了，但你的粉丝数上升了不少。","memeText":"你安静地等热度过去，弹幕说主播很稳。口碑没有受到太大影响，但粉丝数上升了。"}', 49, TRUE),
('NARRATIVE_TEXT', 'TRENDING_TOPIC', 'traffic', '话题上热搜的traffic选择叙事', '{"safeText":"你立刻开播接住流量，弹幕瞬间涌入大量新观众。人气飙升，但弹幕质量在下降。老粉说今天的弹幕没法看了。","trafficText":"你趁热打铁发了相关内容，弹幕说主播太会了。流量接住了，但弹幕质量在下降。口碑略有波动。","memeText":"你高调接住热搜流量，弹幕瞬间炸了。人气飙升的同时，弹幕开始变得不可控。口碑略有下降。"}', 50, TRUE),
('NARRATIVE_TEXT', 'TRENDING_TOPIC', 'meme', '话题上热搜的meme选择叙事', '{"safeText":"你发了一条抽象动态回应热搜，弹幕笑疯了。流量自然发酵，没有反噬。口碑上升了。","trafficText":"你玩梗回应热搜，弹幕说主播太会了。流量接住了，弹幕质量没有下降。口碑上升了。","memeText":"你用幽默化解热搜压力，弹幕笑了一部分。热度慢慢散去了，但口碑稳住了。"}', 51, TRUE),
('NARRATIVE_TEXT', 'DD叛变', 'safe', 'DD流失的safe选择叙事', '{"safeText":"你不理会DD的流失，做好自己的内容。弹幕说主播很稳，留下来的粉丝更加坚定了。口碑没有受到太大影响。","trafficText":"你选择不回应DD流失，专注内容。弹幕说主播很专业，留下来的粉丝质量更高了。口碑稳住了。","memeText":"你安静地做好自己的事，弹幕说主播很稳。DD流失了，但真爱粉更加支持你了。"}', 52, TRUE),
('NARRATIVE_TEXT', 'DD叛变', 'traffic', 'DD流失的traffic选择叙事', '{"safeText":"你搞活动吸引DD回来，弹幕说主播在挽回。部分DD回来了，但粘性还是不高。口碑略有波动。","trafficText":"你高调搞了个活动，弹幕说主播在努力。DD回来了一些，但活动结束后又走了。口碑略有下降。","memeText":"你公开呼吁DD回来，弹幕说主播在挽留。DD表示你很真诚，但还是去了别的直播间。口碑稳住了。"}', 53, TRUE),
('NARRATIVE_TEXT', 'DD叛变', 'meme', 'DD流失的meme选择叙事', '{"safeText":"你说DD来去自由，弹幕笑疯了。DD表示你很洒脱，口碑没有受到太大影响。","trafficText":"你玩梗回应DD流失，弹幕说主播太会了。DD被你逗笑了，口碑稳住了。","memeText":"你用幽默化解DD流失，弹幕笑了一部分。DD表示你很有趣，口碑稳住了。"}', 54, TRUE),
('NARRATIVE_TEXT', 'OLD_FAN_ESSAY', 'safe', '老粉写小作文的safe选择叙事', '{"safeText":"你在直播中感谢老粉的用心，弹幕说主播很真诚。老粉表示满意，口碑上升了。","trafficText":"你选择低调感谢，不搞花活。弹幕说主播很稳，老粉表示理解。口碑稳住了。","memeText":"你安静地表达感谢，弹幕说主播很真诚。口碑上升了，老粉更加支持你了。"}', 55, TRUE),
('NARRATIVE_TEXT', 'OLD_FAN_ESSAY', 'traffic', '老粉写小作文的traffic选择叙事', '{"safeText":"你公开回应老粉的小作文，弹幕瞬间炸了。支持你的人很多，但也有人说你在表演。口碑略有波动。","trafficText":"你高调感谢老粉，弹幕说主播很会做人。口碑上升了，但有人说你太会营销了。","memeText":"你搞了个感谢直播，弹幕说主播很用心。口碑上升了，但直播数据没有预期的好。"}', 56, TRUE),
('NARRATIVE_TEXT', 'OLD_FAN_ESSAY', 'meme', '老粉写小作文的meme选择叙事', '{"safeText":"你用幽默回应老粉的小作文，弹幕笑疯了。老粉表示很开心，口碑上升了。","trafficText":"你玩梗感谢老粉，弹幕说主播太会了。老粉被你逗笑了，口碑上升了。","memeText":"你用搞笑方式回应老粉，弹幕笑了一部分。老粉表示主播很有趣，口碑稳住了。"}', 57, TRUE),
('NARRATIVE_TEXT', 'DATA_LEAK', 'safe', '信息泄露的safe选择叙事', '{"safeText":"你走法律途径处理，弹幕说主播很认真。泄露的信息被控制住了，口碑没有受到太大影响。","trafficText":"你选择低调处理，不公开回应。弹幕不知道发生了什么，但泄露的信息慢慢被遗忘了。","memeText":"你安静地报警处理，弹幕说主播很稳。口碑没有受到太大影响，事情过去了。"}', 58, TRUE),
('NARRATIVE_TEXT', 'DATA_LEAK', 'traffic', '信息泄露的traffic选择叙事', '{"safeText":"你公开谴责泄露行为，弹幕瞬间炸了。支持你的人很多，但也有人说你在炒作。口碑略有波动。","trafficText":"你高调维权，弹幕说主播很勇敢。泄露的信息被更多人知道了，口碑略有下降。","memeText":"你公开声明谴责泄露，弹幕说主播很认真。泄露的信息传播得更广了，口碑下降了。"}', 59, TRUE),
('NARRATIVE_TEXT', 'DATA_LEAK', 'meme', '信息泄露的meme选择叙事', '{"safeText":"你用幽默化解信息泄露，弹幕笑疯了。泄露的信息被当成了梗，口碑没有受到太大影响。","trafficText":"你玩梗回应信息泄露，弹幕说主播太会了。泄露的信息变成了节目效果，口碑稳住了。","memeText":"你用抽象方式回应，弹幕笑了一部分。泄露的信息没有造成太大影响，口碑稳住了。"}', 60, TRUE);

