('TERM_GLOSSARY', 'VUP', 'DEFAULT', '虚拟主播', '{"displayName":"VUP","tooltipText":"虚拟主播，用虚拟形象进行直播的创作者","example":"你就是一个VUP，用30天证明自己"}', 1, TRUE),
('TERM_GLOSSARY', 'TRUE_FAN', 'DEFAULT', '真爱粉', '{"displayName":"真爱粉","tooltipText":"稳定支持你的忠实观众，不容易流失","example":"真爱粉会在你低谷时依然支持你"}', 2, TRUE),
('TERM_GLOSSARY', 'DD', 'DEFAULT', 'DD', '{"displayName":"DD","tooltipText":"多推人，同时关注多个主播的观众，流动性强","example":"DD坐了一站就下车了"}', 3, TRUE),
('TERM_GLOSSARY', 'UNICORN', 'DEFAULT', '独角兽', '{"displayName":"独角兽","tooltipText":"对主播有强烈占有欲的粉丝，不希望主播和别人互动","example":"联动可以，但别太熟"}', 4, TRUE),
('TERM_GLOSSARY', 'MEME', 'DEFAULT', '梗', '{"displayName":"梗","tooltipText":"在弹幕和评论区反复出现的流行语或笑话","example":"标题组提前上班已经成为经典梗"}', 5, TRUE),
('TERM_GLOSSARY', 'CLIP', 'DEFAULT', '切片', '{"displayName":"切片","tooltipText":"从直播中截取的精彩片段，由切片组制作","example":"这个三秒的反应被做成了切片"}', 6, TRUE),
('TERM_GLOSSARY', 'DEBT', 'DEFAULT', '债务', '{"displayName":"债务","tooltipText":"因为之前的选择或行为产生的潜在风险","example":"标题党反噬就是一种债务"}', 7, TRUE),
('TERM_GLOSSARY', 'MILINE', 'DEFAULT', '米线', '{"displayName":"米线","tooltipText":"边界感，主播和粉丝之间的心理距离","example":"米线施工队今天短暂上班"}', 8, TRUE),
('TERM_GLOSSARY', 'SC', 'DEFAULT', '高亮互动', '{"displayName":"SC","tooltipText":"游戏内模拟的高亮留言/直播间高亮互动，不连接现实交易","example":"主播认真读了每一条SC高亮留言"}', 9, TRUE),
('TERM_GLOSSARY', 'HEAT', 'DEFAULT', '热度', '{"displayName":"热度","tooltipText":"直播间的人气指标，受观众数、互动等影响","example":"今天的热度像烟花"}', 10, TRUE),
('TERM_GLOSSARY', 'ROUTE', 'DEFAULT', '路线', '{"displayName":"路线","tooltipText":"主播的发展方向，如歌势、切片、联动等","example":"路线锁定了，老粉表示支持"}', 11, TRUE),
('TERM_GLOSSARY', 'ENDING', 'DEFAULT', '结局', '{"displayName":"结局","tooltipText":"30天结束后的最终评价，取决于你的选择","example":"光荣毕业是最好的结局之一"}', 12, TRUE),
('TERM_GLOSSARY', 'REPUTATION', 'DEFAULT', '口碑', '{"displayName":"口碑","tooltipText":"粉丝和路人对你的评价，影响粉丝结构","example":"口碑好的主播更容易吸引真爱粉"}', 13, TRUE),
('TERM_GLOSSARY', 'MOD', 'DEFAULT', '房管', '{"displayName":"房管","tooltipText":"直播间管理员，负责维护弹幕秩序","example":"房管手速拉满，控场中"}', 14, TRUE),
('TERM_GLOSSARY', 'SLICE_GROUP', 'DEFAULT', '切片组', '{"displayName":"切片组","tooltipText":"自发为直播做切片的粉丝群体","example":"切片组说素材管够"}', 15, TRUE);

