('VUP_DIALOGUE', 'DIALOGUE_3', 'DAY_1', '弹幕好多人，我有点不知道说什么了。', '{"mood":"nervous","context":"DAY_1"}', 3, TRUE),
('VUP_DIALOGUE', 'DIALOGUE_4', 'DAY_1', '谢谢大家来看我的第一次直播。', '{"mood":"nervous","context":"DAY_1"}', 4, TRUE),
