('VUP_DIALOGUE', 'DIALOGUE_6', 'DAY_1', '出道日快乐！虽然只有我一个人在说。', '{"mood":"nervous","context":"DAY_1"}', 6, TRUE),
('VUP_DIALOGUE', 'DIALOGUE_7', 'DAY_1', '第一次用虚拟形象直播，感觉好奇怪。', '{"mood":"nervous","context":"DAY_1"}', 7, TRUE),
('VUP_DIALOGUE', 'DIALOGUE_8', 'DAY_1', '今天的弹幕好热闹，我有点接不住。', '{"mood":"nervous","context":"DAY_1"}', 8, TRUE),
