('VUP_DIALOGUE', 'DIALOGUE_10', 'DAY_1', '谢谢今天的观众，我会继续努力的。', '{"mood":"nervous","context":"DAY_1"}', 10, TRUE),
('VUP_DIALOGUE', 'DIALOGUE_11', 'DAY_7', '直播一周了，感觉时间过得好快。', '{"mood":"happy","context":"DAY_7"}', 11, TRUE),
('VUP_DIALOGUE', 'DIALOGUE_12', 'DAY_7', '一周了，我已经开始习惯直播了。', '{"mood":"happy","context":"DAY_7"}', 12, TRUE),
('VUP_DIALOGUE', 'DIALOGUE_13', 'DAY_7', '今天是出道一周纪念，谢谢大家的陪伴。', '{"mood":"happy","context":"DAY_7"}', 13, TRUE),
('VUP_DIALOGUE', 'DIALOGUE_14', 'DAY_7', '一周了，弹幕比第一天好接了。', '{"mood":"happy","context":"DAY_7"}', 14, TRUE),
('VUP_DIALOGUE', 'DIALOGUE_15', 'DAY_7', '直播一周了，我开始有自己的节奏了。', '{"mood":"happy","context":"DAY_7"}', 15, TRUE),
