('PLATFORM_EVENT', 'PLATFORM_EVENT_WEEK1_A', 'WEEK1', '平台新人扶持期', '{"title":"新人扶持期","description":"平台给新人主播一周的流量扶持，你的直播间获得了额外曝光。","effect":"人气+15，DD+10","period":"week1"}', 1, TRUE),
