('PLATFORM_EVENT', 'PLATFORM_EVENT_WEEK2_B', 'WEEK2', '平台活动邀请', '{"title":"平台活动邀请","description":"平台邀请你参加一个官方活动，可以增加曝光。","effect":"人气+8，平台关系+3","period":"week2"}', 5, TRUE),
