('PLATFORM_EVENT', 'PLATFORM_EVENT_WEEK3_A', 'WEEK3', '平台月度评选', '{"title":"月度评选","description":"平台开始月度主播评选，你被提名了。","effect":"人气+12，口碑+8","period":"week3"}', 7, TRUE),
('PLATFORM_EVENT', 'PLATFORM_EVENT_WEEK3_B', 'WEEK3', '平台商业化邀请', '{"title":"商业化邀请","description":"平台邀请你加入商业化计划。","effect":"商业化+10，口碑-3","period":"week3"}', 8, TRUE),
('PLATFORM_EVENT', 'PLATFORM_EVENT_WEEK3_C', 'WEEK3', '平台数据报告', '{"title":"数据报告","description":"平台给你发了一份详细的数据报告。","effect":"无直接影响，可参考数据","period":"week3"}', 9, TRUE),
('PLATFORM_EVENT', 'PLATFORM_EVENT_WEEK4_A', 'WEEK4', '平台月末冲刺', '{"title":"月末冲刺","description":"平台鼓励主播月末冲刺，给予额外流量支持。","effect":"人气+10","period":"week4"}', 10, TRUE),
('PLATFORM_EVENT', 'PLATFORM_EVENT_WEEK4_B', 'WEEK4', '平台总结邀请', '{"title":"总结邀请","description":"平台邀请你做一个30天总结直播。","effect":"人气+15，口碑+5","period":"week4"}', 11, TRUE),
('PLATFORM_EVENT', 'PLATFORM_EVENT_WEEK4_C', 'WEEK4', '平台毕业季活动', '{"title":"毕业季活动","description":"平台举办毕业季活动，邀请你参加。","effect":"人气+10，口碑+5","period":"week4"}', 12, TRUE);

