('ROUTE_STORY', 'ROUTE_STORY_COLLAB_EARLY', 'SOCIAL_COLLAB', '联动路线：首次联动', '{"title":"首次联动","description":"你完成了第一次正式联动，弹幕说化学反应很好。","route":"SOCIAL_COLLAB","timepoint":"early","effect":"DD+10，联动证据+1"}', 5, TRUE),
