('ROUTE_STORY', 'ROUTE_STORY_BLACKRED_LATE', 'BLACK_RED_MAIN_STAGE', '黑红路线：主会场就位', '{"title":"主会场就位","description":"你已经成为争议的中心人物，主会场灯亮了。","route":"BLACK_RED_MAIN_STAGE","timepoint":"late","effect":"人气+30，口碑-10"}', 10, TRUE),
